const data = $input.first().json;
const raw = String(data.message_text ?? '').replace(/^REGISTER\s*/i, '');
const [name = 'Demo Farmer', district = 'Demo District', crop = 'maize'] = raw.split(',').map((part) => part.trim()).filter(Boolean);
return [{ json: { ...data, registration_name: name, registration_district: district, registration_crop: crop } }];

const data = $input.first().json;
const text = data.output?.[0]?.content?.[0]?.text ?? data.ai_response ?? '';
let classified = {};
try { classified = JSON.parse(text); } catch { classified = { intent: 'unknown', confidence: 0, reason: 'Demo parser could not read AI JSON.' }; }
return [{ json: { ...data, ai_intent: classified.intent ?? 'unknown', ai_confidence: classified.confidence ?? 0, ai_reason: classified.reason ?? '' } }];
